export type { CardOperationsDeps }

/** The card-facing surface of the data service, delegating to focused operation modules. */
export class CardOperations {
    private readonly context: CardOperationContext
    private readonly archives: CardArchiveOperations
    private readonly internalIds: CardInternalIdOperations
    private readonly projectFiles: ProjectFileOperations
    private readonly renames: CardRenameOperations
    private readonly triggerStateActions: (cardPath: string, state: string) => void

    constructor(
        dependencies: CardOperationsDeps,
        triggerStateActions: (cardPath: string, state: string) => void,
    ) {
        this.context = new CardOperationContext(dependencies)
        this.triggerStateActions = triggerStateActions
        this.archives = new CardArchiveOperations(this.context, triggerStateActions)
        this.renames = new CardRenameOperations(this.context)
        this.internalIds = new CardInternalIdOperations(this.context, () => this.renames.reset())
        this.projectFiles = new ProjectFileOperations(this.context)
    }

    async createCard(draft: CardDraft) {
        const { config, project } = this.context.requireProject('create a card')
        const { dependencies } = this.context

        const file = createCardFile(
            dependencies.files(),
            config.workingFolder,
            config.cardSeparator,
            config.cardTypes,
            config.cardBodyTemplate,
            config.states[0].state,
            draft,
        )
        dependencies.replaceFiles([...dependencies.files(), file], config.workingFolder)
        await this.context.commitAndMergeFiles({
            branch: project.branch,
            files: [file],
            message: `Create ${file.path}`,
        }, [file])
        await this.context.pushCreatedItem('Card')

        dependencies.refreshSnapshot(config.workingFolder)
        telemetryService.trackEvent('create_card')

        return file
    }

    createFolder(parentDirectory: string, name: string) {
        return this.projectFiles.createFolder(parentDirectory, name)
    }

    createMarkdownFile(parentDirectory: string, name: string) {
        return this.projectFiles.createMarkdownFile(parentDirectory, name)
    }

    updateCardBody(path: string, body: string, saveReference?: OpenDocumentSaveReference) {
        const existingFile = this.context.dependencies.requireFile(path)

        return this.saveFile(
            { content: markdownParsingService.replaceBody(existingFile.content, body), path, sha: existingFile.sha },
            saveReference,
        )
    }

    updateCardAffects(path: string, affects: string[]) {
        return this.context.saveCardContentChange(path, (content) => markdownParsingService.setAffects(content, affects))
    }

    updateCardHeaderFields(path: string, updates: Record<string, string>, saveReference?: OpenDocumentSaveReference) {
        return this.context.saveCardContentChange(
            path,
            (content) => markdownParsingService.rewriteHeader(content, updates),
            saveReference,
        )
    }

    updateCardWorktree(path: string, worktree: number | null) {
        return this.context.saveCardContentChange(path, (content) => markdownParsingService.setWorktree(content, worktree))
    }

    toggleCardPolicy(path: string, policyKey: string, saveReference?: OpenDocumentSaveReference) {
        const { config } = this.context.dependencies.requireDependencies()
        const existingFile = this.context.dependencies.requireFile(path)
        const card = markdownParsingService.parseCard(existingFile, config.workingFolder)
        const enabled = card.header.policy[policyKey] ?? false

        return this.context.saveCardContentChange(
            path,
            (content) => markdownParsingService.setPolicyFlag(content, policyKey, !enabled),
            saveReference,
        )
    }

    ensureCardInternalIds() {
        return this.internalIds.ensureCardInternalIds()
    }

    updateCardTitle(path: string, title: string, saveReference?: OpenDocumentSaveReference) {
        return this.renames.updateCardTitle(path, title, saveReference)
    }

    async moveCard(cardPath: string, targetStatus: string, targetIndex: number) {
        if (targetStatus === 'archived') return this.archives.archiveCard(cardPath, targetIndex)

        const activeCards = this.context.dependencies.snapshot()?.activeCards ?? []
        const movedCard = activeCards.find((card) => card.path === cardPath)
        const previousStatus = movedCard?.header.status ?? null
        const updates = computeMove(activeCards, cardPath, targetStatus, targetIndex)

        this.saveCardMoveUpdates(cardPath, updates)

        if (movedCard && previousStatus !== targetStatus) this.triggerStateActions(movedCard.path, targetStatus)

        return updates
    }

    /** Applies every ordering link from one move to local state and one persistence batch. */
    private saveCardMoveUpdates(cardPath: string, updates: CardMoveUpdate[]) {
        if (updates.length === 0) return

        const { commitBatcher, project } = this.context.requireProject('move a card')
        const openDocumentsByPath = new Map(updates.map(({ path }) => [path, this.context.findOpenCardDocument(path)]))
        const updatedFiles = this.context.applyOrderingUpdates(updates)
        this.context.replaceUpdatedFiles(updatedFiles)

        const changes = updatedFiles.map((file) => attachSaveReference(
            file,
            this.context.resyncOpenCardDocument(openDocumentsByPath.get(file.path) ?? null, file.path, undefined, 'Moved'),
        ))
        commitBatcher.schedule(project.branch, changes, `Move ${cardPath}`)
        this.context.dependencies.dispatchChanged()
    }

    async deleteCard(path: string) {
        const card = this.context.dependencies.snapshot()?.activeCards.find((currentCard) => currentCard.path === path)
        if (!card) throw new Error(`Cannot delete an active card that is not loaded: ${path}`)

        return this.projectFiles.deleteProjectFile(path, true)
    }

    async deleteFile(path: string) {
        const { dependencies } = this.context
        const loadedFile = dependencies.files().some((file) => file.path === path)
        const repositoryFile = dependencies.snapshot()?.repositoryFiles.includes(path) ?? false
        if (!loadedFile && !repositoryFile) throw new Error(`Cannot delete a file that is not loaded: ${path}`)

        const activeCard = dependencies.snapshot()?.activeCards.some((card) => card.path === path) ?? false

        return this.projectFiles.deleteProjectFile(path, activeCard)
    }

    deleteFolder(path: string) {
        return this.projectFiles.deleteFolder(path)
    }

    saveFile(file: MarkdownFile, saveReference?: OpenDocumentSaveReference) {
        return this.context.saveFile(file, saveReference)
    }

    saveProjectFile(file: MarkdownFile, message: string) {
        return this.projectFiles.saveProjectFile(file, message)
    }

    flushPendingCommits() {
        return this.context.flushPendingCommits()
    }

    commitFiles(request: CommitRequest) {
        return this.context.commitFiles(request)
    }

    commitAndMergeFiles(request: CommitRequest, fallbackFiles: MarkdownFile[] = []) {
        return this.context.commitAndMergeFiles(request, fallbackFiles)
    }
}

}

/** Owns project menu service calls and non-dialog session state. */
export function useProjectToolbarMenuActions(args: UseProjectToolbarMenuActionsArgs) {
    const { accessToken, isGithubAuthenticated, onCloseDialog, onOpenDialog } = args
    const { project, snapshot } = useProjectState()
    const projectSession = useProjectSession()
    const projectConfig = useProjectConfig()
    const electronBridge = useMemo(() => getElectronDataBridge(), [])
    const [branches, setBranches] = useState<BranchReference[]>(EMPTY_BRANCHES)
    const [isReleaseCompleting, setIsReleaseCompleting] = useState(false)
    const [projectOpenResolution, setProjectOpenResolution] = useState<ProjectOpenResolution | null>(null)
    const [initialProjectSource, setInitialProjectSource] = useState<ProjectDialogSource | null>(null)
    const [initialRemoteProject, setInitialRemoteProject] = useState<ProjectReference | null>(null)
    const [repositories, setRepositories] = useState<RepositoryReference[]>(EMPTY_REPOSITORIES)
    const [switchBranch, setSwitchBranch] = useState(project?.branch ?? '')
    const activeCards = snapshot?.activeCards ?? []
    const cardTypes = projectConfig?.cardTypes ?? DEFAULT_CARD_TYPES
    const cardBodyTemplate = projectConfig?.cardBodyTemplate ?? DEFAULT_CARD_BODY_TEMPLATE
    const pushMode = (projectConfig?.pushMode ?? 'auto') as PushMode

    const closeDialog = useCallback(() => {
        onCloseDialog()
        setProjectOpenResolution(null)
        projectSessionService.setError(null)
    }, [onCloseDialog])

    const openProject = useCallback(async (storageType: StorageType, nextProject: ProjectReference) => {
        setProjectOpenResolution(null)

        try {
            const resolution = await projectSessionService.openProject(storageType, nextProject, accessToken)
            if (resolution) {
                setProjectOpenResolution(resolution)
                onOpenDialog('open')

                return
            }

            closeDialog()
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }, [accessToken, closeDialog, onOpenDialog])

    const openElectronProject = useCallback(async () => {
        if (!electronBridge) return

        let nextProject: ProjectReference | null
        try {
            nextProject = await electronBridge.openProjectFolder()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Local project selection failed' })

            return
        }

        if (nextProject) await openProject('local', nextProject)
    }, [electronBridge, openProject])

    const loadRepositories = useCallback(async () => {
        try {
            setRepositories(await projectSessionService.listRepositories(accessToken))
        } catch {
            setRepositories(EMPTY_REPOSITORIES)
        }
    }, [accessToken])

    const loadSwitchBranches = useCallback(async () => {
        if (!project) return

        try {
            const storageType = project.rootPath ? 'local' : 'github'
            const nextBranches = await projectSessionService.listBranches(storageType, project, accessToken)
            setBranches(nextBranches)
            setSwitchBranch(branchValue(nextBranches, project.branch))
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }, [accessToken, project])

    useEffect(() => {
        const handleOpenProjectDialog = (event: Event) => {
            if (electronBridge) {
                void openElectronProject()
                return
            }

            const detail = (event as CustomEvent<OpenProjectDialogDetail>).detail
            setInitialProjectSource(detail?.source ?? null)
            setInitialRemoteProject(detail?.project ?? null)
            setProjectOpenResolution(detail?.resolution ?? null)
            onOpenDialog('open')
            if (isGithubAuthenticated) void loadRepositories()
        }

        window.addEventListener(OPEN_PROJECT_DIALOG_EVENT, handleOpenProjectDialog)

        return () => window.removeEventListener(OPEN_PROJECT_DIALOG_EVENT, handleOpenProjectDialog)
    }, [electronBridge, isGithubAuthenticated, loadRepositories, onOpenDialog, openElectronProject])

    useEffect(() => {
        const handleOpenNewCardDialog = () => {
            if (project) onOpenDialog('card')
        }

        window.addEventListener(OPEN_NEW_CARD_DIALOG_EVENT, handleOpenNewCardDialog)

        return () => window.removeEventListener(OPEN_NEW_CARD_DIALOG_EVENT, handleOpenNewCardDialog)
    }, [onOpenDialog, project])

    const openProjectDialog = () => {
        if (electronBridge) {
            void openElectronProject()
            return
        }

        setInitialProjectSource(null)
        setInitialRemoteProject(null)
        onOpenDialog('open')
        if (isGithubAuthenticated) void loadRepositories()
    }

    const openBranchDialog = () => {
        onOpenDialog('branch')
        void loadSwitchBranches()
    }

    const clearOpenDialogState = () => {
        setBranches(EMPTY_BRANCHES)
        setProjectOpenResolution(null)
    }

    const loadRepositoryBranches = async (repository: RepositoryReference) => {
        try {
            const nextBranches = await projectSessionService.listBranches('github', repository, accessToken)
            setBranches(nextBranches)

            return nextBranches
        } catch {
            setBranches(EMPTY_BRANCHES)

            return EMPTY_BRANCHES
        }
    }

    const loadManualBranches = async (owner: string, repositoryName: string) => {
        try {
            const result = await projectSessionService.findGithubRepositoryBranches(owner, repositoryName, accessToken)
            setBranches(result.branches)

            return result
        } catch {
            return null
        }
    }

    const createRemoteProject = (rootPath: string, branch: string): ProjectReference | null => {
        try {
            if (rootPath.length === 0) throw new Error('Missing remote project root path')

            return { branch: branch || 'main', id: rootPath, rootPath }
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Remote project could not be created' })

            return null
        }
    }

    const loadRemoteBranches = async (endpoint: string, token: string, rootPath: string, branch: string) => {
        const remoteProject = createRemoteProject(rootPath, branch)
        if (!remoteProject) {
            setBranches(EMPTY_BRANCHES)

            return EMPTY_BRANCHES
        }

        projectSessionService.configureRemote(endpoint, token)

        try {
            const nextBranches = await projectSessionService.listBranches('remote', remoteProject, accessToken)
            setBranches(nextBranches)

            return nextBranches
        } catch {
            setBranches(EMPTY_BRANCHES)

            return EMPTY_BRANCHES
        }
    }

    const openGithubProject = async (owner: string, repositoryName: string, branch: string) => {
        try {
            const result = await projectSessionService.findGithubRepositoryBranches(owner, repositoryName, accessToken)
            const fallbackBranches = branches.length > 0 ? branches : result.branches
            const selectedBranch = branch || branchValue(fallbackBranches, result.repository.branch)
            setBranches(fallbackBranches)
            await openProject('github', { ...result.repository, branch: selectedBranch })
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    const openRemoteProject = async (endpoint: string, token: string, nextProject: ProjectReference) => {
        projectSessionService.configureRemote(endpoint, token)
        await openProject('remote', nextProject)
    }

    const openWorkingFolder = async (folder: TopLevelFolderReference) => {
        if (projectOpenResolution?.kind !== 'missing-working-folder') return

        try {
            await projectSessionService.openWorkingFolder(projectOpenResolution, folder, accessToken)
            closeDialog()
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    const createWorkingFolder = async () => {
        if (projectOpenResolution?.kind !== 'missing-working-folder') return

        try {
            await projectSessionService.createWorkingFolder(projectOpenResolution, accessToken)
            closeDialog()
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    const createProjectFolders = async (projectFolder: string) => {
        if (projectOpenResolution?.kind !== 'project-folder-setup') return

        try {
            await projectSessionService.createProjectFolders(projectOpenResolution, projectFolder, accessToken)
            closeDialog()
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    const switchProjectBranch = async (branch: string) => {
        try {
            await projectSessionService.switchBranch(branch)
            closeDialog()
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    const completeRelease = async (releaseName: string) => {
        setIsReleaseCompleting(true)
        try {
            await projectSessionService.completeRelease(releaseName)
            closeDialog()
        } catch {
            // ProjectSessionService emits the user-visible error.
        } finally {
            setIsReleaseCompleting(false)
        }
    }

    const createCard = async (draft: CardDraft) => {
        await projectSessionService.createCard(draft)
        closeDialog()
    }

    return {
        activeCards,
        branches,
        cardBodyTemplate,
        cardTypes,
        clearOpenDialogState,
        closeDialog,
        commit: () => projectSessionService.commit(),
        completeRelease,
        initialProjectSource,
        initialRemoteProject,
        createCard,
        createProjectFolders,
        createRemoteProject,
        createWorkingFolder,
        isLoading: projectSession.isLoading,
        isDesktopMode: !!electronBridge,
        isProjectOpen: !!project,
        isReleaseCompleting,
        loadSwitchBranches,
        loadManualBranches,
        loadRemoteBranches,
        loadRepositoryBranches,
