import type { ProjectReference } from '../data/data_types'
import type { ProjectOpenResolution } from '../services/project/project_session_service'

export const OPEN_PROJECT_DIALOG_EVENT = 'md2:open-project-dialog'
export const OPEN_NEW_CARD_DIALOG_EVENT = 'md2:open-new-card-dialog'

export type ProjectDialogSource = 'github' | 'remote'

export interface OpenProjectDialogDetail {
    project?: ProjectReference
    resolution?: ProjectOpenResolution
    source?: ProjectDialogSource
}

export function requestOpenProjectDialog(source?: ProjectDialogSource, project?: ProjectReference, resolution?: ProjectOpenResolution) {
    window.dispatchEvent(new CustomEvent<OpenProjectDialogDetail>(OPEN_PROJECT_DIALOG_EVENT, { detail: { project, resolution, source } }))
}

export function requestOpenNewCardDialog() {
    window.dispatchEvent(new CustomEvent(OPEN_NEW_CARD_DIALOG_EVENT))
}

import { Box, Chip, IconButton, Paper, Tooltip, Typography } from '@mui/material'
import { SortableContext, verticalListSortingStrategy } from '@dnd-kit/sortable'
import Plus from 'mdi-material-ui/Plus'
import { useCallback, useSyncExternalStore } from 'react'
import type { ReactNode } from 'react'
import type { CardTypeConfig } from '../../data/data_types'
import { requestOpenNewCardDialog } from '../project_command_events'
import { CardColumnEndDropTarget } from './card_column_end_drop_target'
import { cardDragDropService } from './card_drag_drop_service'
import { ProjectCardView, type CardHandlers } from './project_card_view'
import type { VisibleCardColumn } from './use_card_view_columns'
import { useCardColumnCards } from './use_card_column_cards'

const MIN_COLUMN_WIDTH = 200
const MAX_COLUMN_WIDTH = 320

interface CardColumnProps extends CardHandlers {
    cardTypes: CardTypeConfig[]
    column: VisibleCardColumn
    isMobile: boolean
}

/** One status column: a polished droppable stack with header metadata and an empty target. */
export function CardColumn(props: CardColumnProps) {
    const {
        cardTypes, column, isMobile,
        ...handlers
    } = props
    const cardPaths = useCardColumnCards(column.status)
    const subscribe = useCallback(
        (listener: () => void) => cardDragDropService.subscribeColumn(column.status, listener),
        [column.status],
    )
    const getSnapshot = useCallback(
        () => cardDragDropService.getColumnPreview(column.status),
        [column.status],
    )
    const dropPreview = useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
    const dropPreviewHeight = dropPreview?.dropPreviewHeight ?? null
    const dropPreviewIndex = dropPreview?.dropPreviewIndex ?? null
    const columnLabel = column.status || 'Unassigned'
    const dropPlaceholder = (
        <Box
            aria-label="Card drop position"
            key="drop-preview"
            sx={{
                bgcolor: 'action.selected',
                border: '1.5px dashed',
                borderColor: 'primary.main',
                borderRadius: 1.25,
                minHeight: dropPreviewHeight ?? 107,
            }}
        />
    )
    const cardElements: ReactNode[] = []
    for (let index = 0; index <= cardPaths.length; index += 1) {
        if (dropPreviewIndex === index) cardElements.push(dropPlaceholder)
        const cardPath = cardPaths[index]
        if (!cardPath) continue

        cardElements.push(
            <ProjectCardView
                key={cardPath}
                cardPath={cardPath}
                cardTypes={cardTypes}
                {...handlers}
            />,
        )
    }

    return (
        <Paper
            aria-label={`${columnLabel} column`}
            sx={{
                bgcolor: 'action.hover',
                borderRadius: 1.5,
                display: 'flex',
                flex: isMobile ? '0 0 auto' : 1,
                flexDirection: 'column',
                gap: 1,
                maxWidth: isMobile ? '100%' : MAX_COLUMN_WIDTH,
                minWidth: isMobile ? '100%' : MIN_COLUMN_WIDTH,
                p: 1,
            }}
        >
            <Box sx={{ alignItems: 'center', display: 'flex', gap: 1, minHeight: 34, pl: 1, pr: 0.5 }}>
                <Box sx={{ bgcolor: column.color, borderRadius: '3px', flexShrink: 0, height: 8, width: 8 }} />
                <Typography
                    component="h2"
                    sx={{ color: 'text.secondary', fontSize: 12, fontWeight: 700, letterSpacing: 0.6, textTransform: 'uppercase' }}
                >
                    {columnLabel}
                </Typography>
                <Chip
                    label={cardPaths.length}
                    size="small"
                    sx={{ bgcolor: 'background.paper', border: 1, borderColor: 'divider', fontSize: 11, height: 20 }}
                />
                <Box sx={{ flex: 1 }} />
                <Tooltip title="New card">
                    <IconButton aria-label={`Add card from ${columnLabel} column`} onClick={requestOpenNewCardDialog} size="small" sx={{ height: 26, width: 26 }}>
                        <Plus sx={{ fontSize: 16 }} />
                    </IconButton>
                </Tooltip>
            </Box>
            <SortableContext items={cardPaths} strategy={verticalListSortingStrategy}>
                {cardElements}
                {cardPaths.length === 0 && dropPreviewIndex === null ? (
                    <Box
                        sx={{
                            border: '1.5px dashed',
                            borderColor: 'divider',
                            borderRadius: 1.25,
                            color: 'text.disabled',
                            fontSize: 12,
                            p: 2,
                            textAlign: 'center',
                        }}
                    >
                        Drop a card here
                    </Box>
                ) : null}
                <CardColumnEndDropTarget status={column.status} />
            </SortableContext>
        </Paper>
    )
}

import { useMemo, useSyncExternalStore } from 'react'
import { statusOf } from '../../data/card_ordering'
import { defaultColumnAccent, type StateConfig } from '../../data/data_types'
import {
    CARD_ADDED_EVENT,
    CARD_CHANGED_EVENT,
    CARD_REMOVED_EVENT,
    dataService,
    type CardAddedEventDetail,
    type CardChangedEventDetail,
    type CardRemovedEventDetail,
    type DataService,
} from '../../services/data/data_service'

export interface VisibleCardColumn {
    color: string
    status: string
}

function areSameColumns(first: VisibleCardColumn[], second: VisibleCardColumn[]) {
    return first.length === second.length && second.every((column, index) => (
        first[index].color === column.color && first[index].status === column.status
    ))
}

class CardViewColumnStore {
    private columns: VisibleCardColumn[]
    private listener: (() => void) | null = null
    private readonly service: DataService
    private readonly states: StateConfig[]
    private readonly statusCounts: Map<string, number>

    constructor(states: StateConfig[], service: DataService) {
        this.service = service
        this.states = states
        this.statusCounts = new Map()
        const cards = service.getState().snapshot?.activeCards ?? []
        for (const card of cards) this.incrementStatus(statusOf(card))
        this.columns = this.visibleColumns()
    }

    readonly getSnapshot = () => this.columns

    readonly subscribe = (listener: () => void) => {
        this.listener = listener
        this.service.addEventListener(CARD_ADDED_EVENT, this.handleCardAdded)
        this.service.addEventListener(CARD_CHANGED_EVENT, this.handleCardChanged)
        this.service.addEventListener(CARD_REMOVED_EVENT, this.handleCardRemoved)

        return () => {
            this.listener = null
            this.service.removeEventListener(CARD_ADDED_EVENT, this.handleCardAdded)
            this.service.removeEventListener(CARD_CHANGED_EVENT, this.handleCardChanged)
            this.service.removeEventListener(CARD_REMOVED_EVENT, this.handleCardRemoved)
        }
    }

    private readonly handleCardAdded = (event: Event) => {
        const { card } = (event as CustomEvent<CardAddedEventDetail>).detail
        this.incrementStatus(statusOf(card))
        this.publishVisibleColumns()
    }

    private readonly handleCardChanged = (event: Event) => {
        const { card, previousCard } = (event as CustomEvent<CardChangedEventDetail>).detail
        const currentStatus = statusOf(card)
        const previousStatus = statusOf(previousCard)
        if (currentStatus === previousStatus) return

        this.decrementStatus(previousStatus)
        this.incrementStatus(currentStatus)
        this.publishVisibleColumns()
    }

    private readonly handleCardRemoved = (event: Event) => {
        const { card } = (event as CustomEvent<CardRemovedEventDetail>).detail
        this.decrementStatus(statusOf(card))
        this.publishVisibleColumns()
    }

    private incrementStatus(status: string) {
        this.statusCounts.set(status, (this.statusCounts.get(status) ?? 0) + 1)
    }

    private decrementStatus(status: string) {
        const nextCount = (this.statusCounts.get(status) ?? 0) - 1
        if (nextCount > 0) {
            this.statusCounts.set(status, nextCount)
        } else {
            this.statusCounts.delete(status)
        }
    }

    private publishVisibleColumns() {
        const nextColumns = this.visibleColumns()
        if (areSameColumns(this.columns, nextColumns)) return

        this.columns = nextColumns
        this.listener?.()
    }

    private visibleColumns() {
        return this.states
            .map(({ alwaysVisible, color, state }, index) => ({
                alwaysVisible,
                color: color ?? defaultColumnAccent(index),
                status: state,
            }))
            .filter(({ alwaysVisible, status }) => alwaysVisible || this.statusCounts.has(status))
            .map(({ color, status }) => ({ color, status }))
    }
}

/** Subscribes only to changes in which configured board columns must be visible. */
export function useCardViewColumns(states: StateConfig[], service: DataService = dataService) {
    const store = useMemo(() => new CardViewColumnStore(states, service), [service, states])

    return useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot)
}

